return ['domain'=>'publishpress-authors','plural-forms'=>'nplurals=1; plural=0;','language'=>'zh_CN','project-id-version'=>'PublishPress Authors 4.20.0','pot-creation-date'=>'2026-11-12T07:29:08+00:00','po-revision-date'=>'2026-11-12 11:15+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Authors'=>'PublishPress Authors','https://wordpress.org/plugins/publishpress-authors/'=>'https://wordpress.org/plugins/publishpress-authors/','PublishPress Authors allows you to add multiple authors and guest authors to WordPress posts'=>'PublishPress Authors 允许您向 WordPress 文章添加多个作者和客座作者','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Upgrade to Pro'=>'升级到专业版','This plugin can be deleted.'=>'此插件可以被删除。','Actions provided by PublishPress plugins.'=>'PublishPress 插件提供的操作。','List Authors'=>'列出作者','Lists PublishPress Authors. Results never include author email addresses.'=>'列出 PublishPress 作者。结果中从不包含作者电子邮件地址。','Get Author'=>'获取作者','Gets one PublishPress Author by term ID. The response never includes an email address.'=>'通过术语 ID 获取一个 PublishPress 作者。响应中从不包含电子邮件地址。','Get Post Authors'=>'获取文章作者','Gets the ordered PublishPress Authors assigned to one editable post. The response never includes author email addresses.'=>'获取分配给一个可编辑文章的有序 PublishPress 作者。响应中从不包含作者电子邮件地址。','Get Author Fields'=>'获取作者字段','Lists enabled author-profile field definitions without exposing profile values.'=>'列出启用的作者资料字段定义，而不暴露资料值。','Author not found.'=>'未找到作者。','Post not found.'=>'未找到文章。','Authors List'=>'作者列表','Display authors list.'=>'显示作者列表。','Title'=>'标题','Layout'=>'布局','Display All Authors (including those who have not written any posts)'=>'显示所有作者（包括那些没有撰写任何文章的作者）','Enable author\'s search box'=>'启用作者搜索框','Limits per page'=>'每页限制','Authors'=>'作者','Order'=>'顺序','Order by'=>'按...排序','Grid Columns'=>'网格列','Author\'s search box field (Seperate multiple fields by comma(\',\'))'=>'作者搜索框字段（用逗号（‘,’）分隔多个字段）','All Authors'=>'所有作者','Guest Authors'=>'客座作者','Users Authors'=>'用户作者','Ascending'=>'升序','Descending'=>'降序','Name'=>'姓名','Post Counts'=>'文章数量','First Name'=>'名','Last Name'=>'姓','Showing authors starting with %s'=>'显示以 %s 开头的作者','Showing all authors'=>'显示所有作者','No authors found.'=>'未找到作者。','Loading authors...'=>'加载作者...','Unable to load authors.'=>'无法加载作者。','Default Search'=>'默认搜索','Search Box'=>'搜索框','Search'=>'搜索','Search authors'=>'搜索作者','Search authors by'=>'按此搜索作者','No recent posts from this author'=>'该作者没有最近的帖子','Request status.'=>'请求状态。','Security error. Kindly reload this page and try again'=>'安全错误。请重新加载此页面并重试','You cannot edit an author profile linked to an administrator account.'=>'您无法编辑与管理员账户关联的作者档案。','You do not have permission to edit this author profile because it is linked to a user account you do not have permission to edit.'=>'您没有权限编辑此作者档案，因为它与您无权编辑的用户账户相关联。','Sorry, this WordPress user is already mapped to another Author. By default, each user can only be connected to one Author profile.'=>'抱歉，该 WordPress 用户已映射到另一位作者。默认情况下，每个用户只能连接到一个作者档案。','Registered User is required.'=>'需要注册用户。','Author URL cannot be empty.'=>'作者 URL 不能为空。','Another user with Author URL already exists.'=>'已存在具有作者 URL 的其他用户。','Author name is required'=>'作者名称是必需的','No post ID provided for Authors_Iterator constructor. Are you not in a loop or is $post not set?'=>'未为 Authors_Iterator 构造函数提供帖子 ID。您是否不在循环中，或者 $post 未设置？','Display name publicly as'=>'公开显示名称为','Email'=>'电子邮件','Author Type'=>'作者类型','Guest Author With User Account'=>'具有用户账户的访客作者','Registered Author With User Account'=>'具有用户账户的注册作者','Guest Author With No User Account'=>'没有用户账户的访客作者','Edit User'=>'编辑用户','Edit Author Profile'=>'编辑作者档案','Create Author Profile'=>'创建作者档案','General'=>'常规','Avatar'=>'头像','Author'=>'作者','Registered User'=>'注册用户','Biographical Info'=>'个人信息','Avatar Source'=>'头像来源','Default Avatar'=>'默认头像','(Uses the %1$s Email field %2$s to find the Gravatar account if default avatar is not uploaded in Authors Settings)'=>'(如果在作者设置中未上传默认头像，则使用 %1$s 电子邮件字段 %2$s 查找 Gravatar 帐户)